import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md","lastUpdated":null}'),l={name:"guide/getting-started.md"};function o(i,t,r,d,c,p){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">还没安装平台？</p><p>请先阅读 <a href="/guide/installation">安装与启动</a>，完成环境准备、软件包下载与数据服务配置后再回来。</p></div><h2 id="登录平台" tabindex="-1">登录平台 <a class="header-anchor" href="#登录平台" aria-label="Permalink to &quot;登录平台&quot;">​</a></h2><p>在浏览器中打开平台地址（生产环境默认 <code>https://&lt;服务器IP&gt;</code>，端口 443；开发环境为 80），进入登录页：</p><ul><li><strong>账号</strong>：默认为 <code>admin</code></li><li><strong>密码</strong>：默认为 <code>123456</code></li><li><strong>记住我</strong>：勾选后浏览器会记住账号密码</li></ul><div class="warning custom-block"><p class="custom-block-title">安全提示</p><ul><li>默认账号密码可通过环境变量 <code>NS_USER</code> / <code>NS_PWD</code> 修改，生产部署时务必修改。</li><li>连续登录失败 3 次账户会被锁定；同一 IP 失败 5 次冻结 1 小时，冻结期间再次失败封禁 1 天。</li><li>平台会话基于 Session + CSRF Token，长时间无操作后需重新登录。</li></ul></div><h2 id="界面布局" tabindex="-1">界面布局 <a class="header-anchor" href="#界面布局" aria-label="Permalink to &quot;界面布局&quot;">​</a></h2><p>登录后进入主界面，整体分为四个区域：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 顶部导航栏：面包屑 · 消息报警 · 中英文切换 · 用户 │</span></span>
<span class="line"><span>├──────────┬─────────────────────────────────────┤</span></span>
<span class="line"><span>│          │                                     │</span></span>
<span class="line"><span>│  左侧    │           主内容区                   │</span></span>
<span class="line"><span>│  菜单    │        （当前页面内容）               │</span></span>
<span class="line"><span>│          │                                     │</span></span>
<span class="line"><span>├──────────┴─────────────────────────────────────┤</span></span>
<span class="line"><span>│ 底部交易面板（可展开/收起，仅桌面端）             │</span></span>
<span class="line"><span>└────────────────────────────────────────────────┘</span></span></code></pre></div><ul><li><strong>顶部导航栏右侧</strong>： <ul><li>🔔 <strong>消息报警配置</strong>：订阅平台事件（登录、订单、成交、通知等）的报警推送；</li><li>🌐 <strong>中英文切换</strong>；</li><li>👤 <strong>退出系统</strong>。</li></ul></li><li><strong>底部交易面板</strong>：所有桌面端页面共享的快捷下单面板，点击中间横条展开/收起。这是手工交易与操盘手训练的核心工具，详见 <a href="/features/sim-trading#手工下单">模拟盘交易</a>。</li></ul><h2 id="首页" tabindex="-1">首页 <a class="header-anchor" href="#首页" aria-label="Permalink to &quot;首页&quot;">​</a></h2><p>首页提供三张折叠卡片，建议新用户先浏览：</p><ol><li><strong>快捷键参考</strong> —— 工作区切换与回放控制的全部快捷键（见下文）；</li><li><strong>术语解释</strong> —— 网关、模组、策略等核心概念的官方定义；</li><li><strong>已购服务</strong> —— 已订阅的数据服务及到期日。</li></ol><h2 id="全局快捷键" tabindex="-1">全局快捷键 <a class="header-anchor" href="#全局快捷键" aria-label="Permalink to &quot;全局快捷键&quot;">​</a></h2><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td>\`Alt + \`\`</td><td>切换到 首页</td></tr><tr><td><code>Alt + 1</code></td><td>切换到 网关管理</td></tr><tr><td><code>Alt + 2</code></td><td>切换到 模组管理</td></tr><tr><td><code>Alt + 8</code></td><td>切换到 活跃行情报价</td></tr><tr><td><code>Alt + 9</code></td><td>切换到 多图同列</td></tr><tr><td><code>Alt + 0</code></td><td>切换到 平台日志</td></tr><tr><td><code>Alt + Q</code></td><td>回放：数据预加载 / 开始回放 / 暂停回放（按当前状态智能切换）</td></tr><tr><td><code>Alt + W</code></td><td>回放：逐K回放（步进一根K线）</td></tr><tr><td><code>Alt + S</code></td><td>回放：状态重置</td></tr></tbody></table><h2 id="推荐使用路径" tabindex="-1">推荐使用路径 <a class="header-anchor" href="#推荐使用路径" aria-label="Permalink to &quot;推荐使用路径&quot;">​</a></h2><p>第一次使用平台，建议按以下顺序体验（尚未安装部署请先看 <a href="/guide/installation">安装与启动</a>）：</p><ol><li><strong><a href="/features/sim-trading">模拟盘交易</a></strong>：创建 SIM 模拟网关 → 出入金 → 手工下单，熟悉交易面板；</li><li><strong><a href="/features/playback">历史回放</a></strong>：创建 PLAYBACK 回放网关 → 在&quot;多图同列&quot;观看历史行情重演；</li><li><strong><a href="/features/training">操盘手训练</a></strong>：回放 + 模拟账户组合，进行手工复盘训练；</li><li><strong><a href="/features/auto-trading">程序化交易</a></strong>：创建回测模组验证策略 → 模拟盘试运行 → 实盘；</li><li><strong><a href="/features/multi-account">多账户交易</a></strong>：接入多个实盘账户，统一管理。</li></ol>`,18)])])}const u=a(l,[["render",o]]);export{h as __pageData,u as default};
